import numpy as np
import jax
import jax.numpy as jnp

seq = np.load('/app/data/seq.npz')
seq_x = jnp.array(seq['seq'])
h0 = jnp.array(seq['init'])
Wx = jnp.array(seq['Wx'])
Wh = jnp.array(seq['Wh'])
b = jnp.array(seq['b'])
ref_rnn = np.load('/app/reference/scan_rnn.npy')

# candidate 1: x_t @ Wx + h @ Wh

def run(fn):
    h_last, h_seq = jax.lax.scan(fn, h0, seq_x)
    return np.array(h_seq)

# try different matmul orientations and activations

def step1(h, x_t):
    return jnp.tanh(x_t @ Wx + h @ Wh + b), jnp.tanh(x_t @ Wx + h @ Wh + b)

# step2: Wx @ x_t

def step2(h, x_t):
    return jnp.tanh(Wx @ x_t + Wh @ h + b), jnp.tanh(Wx @ x_t + Wh @ h + b)

# step3: x_t @ Wx + Wh @ h

def step3(h, x_t):
    return jnp.tanh(x_t @ Wx + Wh @ h + b), jnp.tanh(x_t @ Wx + Wh @ h + b)

# step4: Wx @ x_t + h @ Wh

def step4(h, x_t):
    return jnp.tanh(Wx @ x_t + h @ Wh + b), jnp.tanh(Wx @ x_t + h @ Wh + b)

# step5: use relu

def step5(h, x_t):
    h_next = jax.nn.relu(x_t @ Wx + h @ Wh + b)
    return h_next, h_next

# step6: use sigmoid

def step6(h, x_t):
    h_next = jax.nn.sigmoid(x_t @ Wx + h @ Wh + b)
    return h_next, h_next

# step7: maybe use tanh but with Wx.T

def step7(h, x_t):
    h_next = jnp.tanh(x_t @ Wx.T + h @ Wh.T + b)
    return h_next, h_next

# step8: linear (no activation)

def step8(h, x_t):
    h_next = x_t @ Wx + h @ Wh + b
    return h_next, h_next

steps = [step1, step2, step3, step4, step5, step6, step7, step8]
for i, fn in enumerate(steps, 1):
    out = run(fn)
    match = np.allclose(out, ref_rnn)
    print(i, match, out[:2])
